"""Shared contracts for structural extraction adapters."""

from abc import ABC, abstractmethod
from typing import NoReturn

from impromptu_ingestion.contracts import DeckManifest, InputKind, ValidatedInput


class StructuralExtractionError(RuntimeError):
    """A machine-identifiable parser failure safe to return from the worker."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


class RenderingUnsupportedError(RuntimeError):
    """Raised when callers cross the intentionally absent rendering boundary."""


class StructuralAdapter(ABC):
    """Extract structure without claiming visual render fidelity."""

    kind: InputKind

    def _require_kind(self, source: ValidatedInput) -> None:
        if source.kind is not self.kind:
            raise StructuralExtractionError(
                "adapter_kind_mismatch",
                f"{self.__class__.__name__} cannot extract {source.kind.value}",
            )

    @abstractmethod
    def extract(self, source: ValidatedInput) -> DeckManifest:
        """Extract a deterministic structural manifest."""

    @staticmethod
    def render_slides() -> NoReturn:
        raise RenderingUnsupportedError(
            "slide rendering is not configured; structural extraction cannot verify fidelity"
        )

"""python-pptx structural extraction without rendering or notes export."""

import hashlib
from collections.abc import Iterable

from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
from pptx.shapes.base import BaseShape
from pptx.slide import Slide

from impromptu_ingestion.adapters.base import StructuralAdapter, StructuralExtractionError
from impromptu_ingestion.canonical import deck_id, slide_key
from impromptu_ingestion.contracts import (
    ChartElement,
    ChartSeries,
    DeckManifest,
    ExtractionWarning,
    ImageElement,
    InputKind,
    RenderBoundary,
    SlideManifest,
    StructuralElement,
    TableElement,
    TextElement,
    ValidatedInput,
)

_EMU_PER_POINT = 12_700


def _points(value: int) -> float:
    return round(value / _EMU_PER_POINT, 4)


def _position(shape: BaseShape) -> dict[str, float]:
    return {
        "x": _points(shape.left),
        "y": _points(shape.top),
        "width": _points(shape.width),
        "height": _points(shape.height),
    }


def _chart_series(shape: BaseShape) -> tuple[ChartSeries, ...]:
    chart = shape.chart
    return tuple(
        ChartSeries(
            name=str(series.name or ""),
            values=tuple("" if value is None else str(value) for value in series.values),
        )
        for series in chart.series
    )


def _extract_shape(shape: BaseShape) -> StructuralElement | None:
    element_id = f"shape:{shape.shape_id}"
    position = _position(shape)

    if shape.has_table:
        rows = tuple(tuple(cell.text for cell in row.cells) for row in shape.table.rows)
        return TableElement(element_id=element_id, rows=rows, **position)

    if shape.has_chart:
        return ChartElement(
            element_id=element_id,
            chart_type=str(shape.chart.chart_type),
            series=_chart_series(shape),
            **position,
        )

    if shape.shape_type is MSO_SHAPE_TYPE.PICTURE:
        image = shape.image
        pixel_width, pixel_height = image.size
        return ImageElement(
            element_id=element_id,
            content_sha256=hashlib.sha256(image.blob).hexdigest(),
            media_type=image.content_type,
            pixel_width=pixel_width,
            pixel_height=pixel_height,
            **position,
        )

    if shape.has_text_frame:
        text = shape.text_frame.text.strip()
        if text:
            return TextElement(element_id=element_id, text=text, **position)
    return None


def _slide_manifest(
    slide: Slide,
    index: int,
    source_sha256: str,
    width_points: float,
    height_points: float,
) -> SlideManifest:
    elements: list[StructuralElement] = []
    warnings: list[ExtractionWarning] = []
    for shape in slide.shapes:
        element = _extract_shape(shape)
        if element is not None:
            elements.append(element)
        elif shape.shape_type not in {MSO_SHAPE_TYPE.PLACEHOLDER, MSO_SHAPE_TYPE.AUTO_SHAPE}:
            warnings.append(
                ExtractionWarning(
                    code="unsupported_shape",
                    message=f"shape {shape.shape_id} ({shape.shape_type}) was not extracted",
                )
            )

    source_id = f"slide:{slide.slide_id}"
    return SlideManifest(
        slide_key=slide_key(source_sha256, source_id),
        source_index=index,
        source_id=source_id,
        width_points=width_points,
        height_points=height_points,
        elements=tuple(elements),
        warnings=tuple(warnings),
    )


class PptxStructuralAdapter(StructuralAdapter):
    """Extract public slide structure; speaker notes are deliberately never read."""

    kind = InputKind.PPTX
    adapter_version = "python-pptx-structural-v1"

    def extract(self, source: ValidatedInput) -> DeckManifest:
        self._require_kind(source)
        try:
            presentation = Presentation(source.path)
            slides: Iterable[Slide] = presentation.slides
            manifests = tuple(
                _slide_manifest(
                    slide,
                    index,
                    source.source_sha256,
                    _points(presentation.slide_width),
                    _points(presentation.slide_height),
                )
                for index, slide in enumerate(slides, start=1)
            )
        except Exception as error:
            raise StructuralExtractionError(
                "invalid_document", "PPTX structure could not be parsed"
            ) from error

        if not manifests:
            raise StructuralExtractionError("empty_document", "PPTX contains no slides")
        return DeckManifest(
            deck_id=deck_id(source.source_sha256),
            source_sha256=source.source_sha256,
            source_kind=self.kind,
            adapter_version=self.adapter_version,
            slides=manifests,
            render_boundary=RenderBoundary.structural_only(),
        )

"""PyMuPDF positioned structural extraction without rendering or OCR."""

import hashlib
from typing import TypedDict, cast

import pymupdf

from impromptu_ingestion.adapters.base import StructuralAdapter, StructuralExtractionError
from impromptu_ingestion.canonical import deck_id, slide_key
from impromptu_ingestion.contracts import (
    DeckManifest,
    ExtractionWarning,
    ImageElement,
    InputKind,
    RenderBoundary,
    SlideManifest,
    StructuralElement,
    TextElement,
    ValidatedInput,
)


class _PdfSpan(TypedDict):
    text: str
    bbox: tuple[float, float, float, float]


class _PdfLine(TypedDict):
    spans: list[_PdfSpan]


class _PdfBlock(TypedDict, total=False):
    type: int
    bbox: tuple[float, float, float, float]
    lines: list[_PdfLine]
    image: bytes
    ext: str
    width: int
    height: int


class _PdfTextPage(TypedDict):
    blocks: list[_PdfBlock]


def _position(bbox: tuple[float, float, float, float]) -> dict[str, float]:
    x0, y0, x1, y1 = bbox
    return {
        "x": round(max(0.0, x0), 4),
        "y": round(max(0.0, y0), 4),
        "width": round(max(0.0, x1 - x0), 4),
        "height": round(max(0.0, y1 - y0), 4),
    }


def _text_elements(block: _PdfBlock, block_index: int) -> list[TextElement]:
    elements: list[TextElement] = []
    for line_index, line in enumerate(block.get("lines", []), start=1):
        for span_index, span in enumerate(line["spans"], start=1):
            text = span["text"].strip()
            if text:
                elements.append(
                    TextElement(
                        element_id=f"text:{block_index}:{line_index}:{span_index}",
                        text=text,
                        **_position(span["bbox"]),
                    )
                )
    return elements


def _image_element(block: _PdfBlock, block_index: int) -> ImageElement | None:
    content = block.get("image")
    bbox = block.get("bbox")
    if not content or bbox is None:
        return None
    extension = block.get("ext", "unknown").lower()
    media_type = "image/jpeg" if extension in {"jpg", "jpeg"} else f"image/{extension}"
    return ImageElement(
        element_id=f"image:{block_index}",
        content_sha256=hashlib.sha256(content).hexdigest(),
        media_type=media_type,
        pixel_width=block.get("width"),
        pixel_height=block.get("height"),
        **_position(bbox),
    )


def _page_manifest(page: pymupdf.Page, index: int, source_sha256: str) -> SlideManifest:
    structure = cast(_PdfTextPage, page.get_text("dict", sort=True))
    elements: list[StructuralElement] = []
    has_text = False
    has_image = False
    for block_index, block in enumerate(structure["blocks"], start=1):
        if block.get("type") == 0:
            text = _text_elements(block, block_index)
            elements.extend(text)
            has_text = has_text or bool(text)
        elif block.get("type") == 1:
            image = _image_element(block, block_index)
            if image is not None:
                elements.append(image)
                has_image = True

    warnings: list[ExtractionWarning] = []
    if has_image and not has_text:
        warnings.append(
            ExtractionWarning(
                code="scanned_page_requires_ocr",
                message="page has images but no extractable text; OCR/VLM was not performed",
            )
        )
    elif not elements:
        warnings.append(
            ExtractionWarning(
                code="no_extractable_content",
                message="page has no text or image structure; rendering was not performed",
            )
        )

    source_id = f"page:{index}"
    return SlideManifest(
        slide_key=slide_key(source_sha256, source_id),
        source_index=index,
        source_id=source_id,
        width_points=round(page.rect.width, 4),
        height_points=round(page.rect.height, 4),
        elements=tuple(elements),
        warnings=tuple(warnings),
    )


class PdfStructuralAdapter(StructuralAdapter):
    """Extract positioned PDF text and embedded images without rasterizing pages."""

    kind = InputKind.PDF
    adapter_version = "pymupdf-structural-v1"

    def extract(self, source: ValidatedInput) -> DeckManifest:
        self._require_kind(source)
        try:
            with pymupdf.open(source.path) as document:
                if document.needs_pass:
                    raise StructuralExtractionError(
                        "encrypted_document", "encrypted PDFs are not supported"
                    )
                manifests = tuple(
                    _page_manifest(page, index, source.source_sha256)
                    for index, page in enumerate(document, start=1)
                )
        except StructuralExtractionError:
            raise
        except Exception as error:
            raise StructuralExtractionError(
                "invalid_document", "PDF structure could not be parsed"
            ) from error

        if not manifests:
            raise StructuralExtractionError("empty_document", "PDF contains no pages")
        return DeckManifest(
            deck_id=deck_id(source.source_sha256),
            source_sha256=source.source_sha256,
            source_kind=self.kind,
            adapter_version=self.adapter_version,
            slides=manifests,
            render_boundary=RenderBoundary.structural_only(),
        )

"""python-pptx structural extraction without rendering or notes export."""

import hashlib
from collections.abc import Iterable, Sequence
from typing import Protocol, cast

from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
from pptx.shapes.base import BaseShape
from pptx.slide import Slide

from impromptu_ingestion.adapters.base import StructuralAdapter, StructuralExtractionError
from impromptu_ingestion.canonical import deck_id, slide_key
from impromptu_ingestion.contracts import (
    ChartElement,
    ChartSeries,
    DeckManifest,
    ExtractionWarning,
    ImageElement,
    InputKind,
    RenderBoundary,
    SlideManifest,
    StructuralElement,
    TableElement,
    TextElement,
    ValidatedInput,
)

_EMU_PER_POINT = 12_700


class _TableCell(Protocol):
    text: str


class _TableRow(Protocol):
    cells: Sequence[_TableCell]


class _Table(Protocol):
    rows: Sequence[_TableRow]


class _TableShape(Protocol):
    table: _Table


class _Series(Protocol):
    name: object | None
    values: Iterable[object | None]


class _Chart(Protocol):
    chart_type: object
    series: Iterable[_Series]


class _ChartShape(Protocol):
    chart: _Chart


class _Image(Protocol):
    blob: bytes
    content_type: str
    size: tuple[int, int]


class _ImageShape(Protocol):
    image: _Image


class _TextFrame(Protocol):
    text: str


class _TextShape(Protocol):
    text_frame: _TextFrame


def _points(value: int) -> float:
    return round(value / _EMU_PER_POINT, 4)


def _position(shape: BaseShape) -> tuple[float, float, float, float]:
    return (
        _points(shape.left),
        _points(shape.top),
        _points(shape.width),
        _points(shape.height),
    )


def _chart_series(shape: _ChartShape) -> tuple[ChartSeries, ...]:
    return tuple(
        ChartSeries(
            name=str(series.name or ""),
            values=tuple("" if value is None else str(value) for value in series.values),
        )
        for series in shape.chart.series
    )


def _extract_shape(shape: BaseShape) -> StructuralElement | None:
    element_id = f"shape:{shape.shape_id}"
    x, y, width, height = _position(shape)

    if shape.has_table:
        table_shape = cast(_TableShape, shape)
        rows = tuple(tuple(cell.text for cell in row.cells) for row in table_shape.table.rows)
        return TableElement(
            element_id=element_id,
            rows=rows,
            x=x,
            y=y,
            width=width,
            height=height,
        )

    if shape.has_chart:
        chart_shape = cast(_ChartShape, shape)
        return ChartElement(
            element_id=element_id,
            chart_type=str(chart_shape.chart.chart_type),
            series=_chart_series(chart_shape),
            x=x,
            y=y,
            width=width,
            height=height,
        )

    if shape.shape_type is MSO_SHAPE_TYPE.PICTURE:
        image = cast(_ImageShape, shape).image
        pixel_width, pixel_height = image.size
        return ImageElement(
            element_id=element_id,
            content_sha256=hashlib.sha256(image.blob).hexdigest(),
            media_type=image.content_type,
            pixel_width=pixel_width,
            pixel_height=pixel_height,
            x=x,
            y=y,
            width=width,
            height=height,
        )

    if shape.has_text_frame:
        text = cast(_TextShape, shape).text_frame.text.strip()
        if text:
            return TextElement(
                element_id=element_id,
                text=text,
                x=x,
                y=y,
                width=width,
                height=height,
            )
    return None


def _slide_manifest(
    slide: Slide,
    index: int,
    source_sha256: str,
    width_points: float,
    height_points: float,
) -> SlideManifest:
    elements: list[StructuralElement] = []
    warnings: list[ExtractionWarning] = []
    for shape in slide.shapes:
        element = _extract_shape(shape)
        if element is not None:
            elements.append(element)
        elif shape.shape_type not in {MSO_SHAPE_TYPE.PLACEHOLDER, MSO_SHAPE_TYPE.AUTO_SHAPE}:
            warnings.append(
                ExtractionWarning(
                    code="unsupported_shape",
                    message=f"shape {shape.shape_id} ({shape.shape_type}) was not extracted",
                )
            )

    source_id = f"slide:{slide.slide_id}"
    return SlideManifest(
        slide_key=slide_key(source_sha256, source_id),
        source_index=index,
        source_id=source_id,
        width_points=width_points,
        height_points=height_points,
        elements=tuple(elements),
        warnings=tuple(warnings),
    )


class PptxStructuralAdapter(StructuralAdapter):
    """Extract public slide structure; speaker notes are deliberately never read."""

    kind = InputKind.PPTX
    adapter_version = "python-pptx-structural-v1"

    def extract(self, source: ValidatedInput) -> DeckManifest:
        self._require_kind(source)
        try:
            presentation = Presentation(str(source.path))
            slide_width = cast(int, presentation.slide_width)
            slide_height = cast(int, presentation.slide_height)
            slides: Iterable[Slide] = presentation.slides
            manifests = tuple(
                _slide_manifest(
                    slide,
                    index,
                    source.source_sha256,
                    _points(slide_width),
                    _points(slide_height),
                )
                for index, slide in enumerate(slides, start=1)
            )
        except Exception as error:
            raise StructuralExtractionError(
                "invalid_document", "PPTX structure could not be parsed"
            ) from error

        if not manifests:
            raise StructuralExtractionError("empty_document", "PPTX contains no slides")
        return DeckManifest(
            deck_id=deck_id(source.source_sha256),
            source_sha256=source.source_sha256,
            source_kind=self.kind,
            adapter_version=self.adapter_version,
            slides=manifests,
            render_boundary=RenderBoundary.structural_only(),
        )

